function eventHTML(s){const c=childOf(s.childId);return '<div class="schedule-line"><div class="schedule-time">'+s.start+'<small>'+s.end+' 종료</small></div><div class="event-wrap"><button class="event" style="--child-color:'+c.color+'" data-action="schedule" data-id="'+s.id+'" data-event-start="'+s.start+'" data-event-end="'+s.end+'"><div class="event-top"><h3>'+esc(s.title)+'</h3><span class="event-label">'+esc(c.name)+(s.date?' · 이 날짜만':'')+'</span></div><div class="event-meta"><span>'+icon('pin')+' '+esc(s.place||'장소 미지정')+'</span><span>'+icon('clock')+' '+(mins(s.end)-mins(s.start))+'분</span>'+(s.note?'<span title="'+esc(s.note)+'">메모 있음</span>':'')+'</div></button><div class="transport">'+(s.source==='school-plan'&&s.kind!=='school'?'교내 일정 · 별도 차량 이동 없음':icon(s.mode==='walk'?'walk':'car')+'<b>'+esc(MODES[s.mode])+'</b><span>'+clock(mins(s.start)-s.travel)+' 출발 · '+s.travel+'분 이동</span>'+(s.vehicle?'<span class="vehicle">'+esc(s.vehicle)+'</span>':''))+'</div></div></div>';}
