function shiftMonth(m,offset){const d=localDate(m+'-01');d.setMonth(d.getMonth()+offset);return iso(d).slice(0,7);}
const won=n=>renderingMasked13?'금액 비공개':new Intl.NumberFormat('ko-KR').format(n)+'원';
function editPrefs(){editing={type:'prefs'};const p=state.prefs;dialog('첫 화면과 시간 눈금 설정',formWrap('prefs',select('startView','앱을 열 때 기본 보기',[['day','하루 시간표'],['week','일주일 전체']],p.startView)+select('focus','기본으로 보여줄 날짜',[['today','오늘 요일 자동 선택'],['weekday','지정한 요일 우선 표시']],p.focus)+select('weekday','지정 요일 (이번 주 기준)',[1,2,3,4,5,6,0].map(d=>[d,DAYS[d]+'요일']),p.weekday)+'<label class="check-label"><input type="checkbox" name="showNow" '+(p.showNow?'checked':'')+'>현재 시각 눈금 표시</label><p class="help">요일은 월~일로 묶인 이번 주 기준입니다. 화면의 하루 / 주간 버튼으로 언제든 전환할 수 있습니다. 설정은 이 브라우저에 저장되며 현재 시각은 기기 시계 기준입니다.</p>'));}
function timeChart(){const today=iso(new Date()),list=onDate(state,selected,child),kids=state.children.filter(c=>child==='all'||c.id===child);return '<section class="time-chart" aria-label="하루 시간 눈금"><div class="time-chart-title"><b>'+icon('clock')+' 하루 시간 눈금</b><span class="live-clock" data-live-clock></span></div><p class="time-chart-help">'+(selected===today?'오늘 일정 위에 현재 시각을 표시합니다.':'선택한 날짜 '+selected+' · 현재 시각 선은 오늘 날짜에서만 표시됩니다.')+'</p><div class="time-plot"><div class="time-axis"><span>00</span><span>06</span><span>12</span><span>18</span><span>24시</span></div>'+kids.map(c=>'<div class="time-track-row"><span class="track-name">'+esc(c.name)+'</span><div class="time-track">'+list.filter(s=>s.childId===c.id).map(s=>'<button class="time-block travel-block" style="left:'+((mins(s.start)-s.travel)/14.4)+'%;width:'+(s.travel/14.4)+'%;--child-color:'+c.color+'" data-action="schedule" data-id="'+s.id+'" title="'+esc(c.name+' · '+MODES[s.mode]+' '+s.travel+'분 이동')+'" aria-label="'+esc(c.name+' '+s.title+' 이동 '+s.travel+'분')+'"></button><button class="time-block" style="left:'+(mins(s.start)/14.4)+'%;width:'+((mins(s.end)-mins(s.start))/14.4)+'%;--child-color:'+c.color+'" data-action="schedule" data-id="'+s.id+'" title="'+esc(s.title+' '+s.start+'–'+s.end)+'" aria-label="'+esc(c.name+' '+s.title+' '+s.start+'부터 '+s.end)+'">'+esc(s.title)+'</button>').join('')+'</div></div>').join('')+'<div class="now-layer" data-now-layer><i class="now-tick" data-now-tick><span data-now-label></span></i></div></div><div class="time-chart-legend"><i></i>수업 <i class="travel-swatch"></i>이동 <span>상세 시간은 아래 일정에서 확인</span></div></section>';}
function updateClock(){const now=new Date(),today=iso(now),value=clock(now.getHours()*60+now.getMinutes());document.querySelectorAll('[data-live-clock]').forEach(e=>e.textContent='현재 '+value);const layer=$('[data-now-layer]');if(layer){layer.hidden=!state.prefs.showNow||selected!==today;const tick=$('[data-now-tick]');tick.style.left=((now.getHours()*60+now.getMinutes())/14.4)+'%';$('[data-now-label]').textContent=value;tick.style.setProperty('--label-shift',now.getHours()>=22?'-100%':now.getHours()<2?'0%':'-50%');}document.querySelectorAll('[data-event-start]').forEach(e=>e.classList.toggle('in-progress',selected===today&&value>=e.dataset.eventStart&&value<e.dataset.eventEnd));}
function feesSection(){const rows=feeRows(state,feeMonth,child),total=rows.reduce((a,r)=>a+r.amount,0),paid=rows.filter(r=>r.paid).reduce((a,r)=>a+r.amount,0),today=iso(new Date());let last='';return '<section class="fees-section card"><div class="fees-heading"><div><span class="eyebrow">TUITION PLANNER</span><h2>학원비, 빠뜨리지 않도록</h2><p>납부 예정과 실제 완료를 구분해 기록하세요.</p></div><button class="button primary" data-action="fee">'+icon('plus')+'학원비 등록</button></div><div class="fees-toolbar"><div class="period"><button class="icon-button" data-action="fee-month" data-step="-1" aria-label="이전 납부 월">‹</button><b>'+feeMonth.replace('-','년 ')+'월</b><button class="icon-button" data-action="fee-month" data-step="1" aria-label="다음 납부 월">›</button></div><span class="muted">'+(child==='all'?'모든 자녀':esc(childOf(child).name))+' · '+rows.length+'건</span></div><div class="fees-summary"><span>이번 달 합계<strong>'+won(total)+'</strong></span><span>납부 완료<strong>'+won(paid)+'</strong></span><span>미납부 예정액<strong>'+won(total-paid)+'</strong></span></div><div class="fee-list">'+(rows.length?rows.map(r=>{const dateHeader=r.dueDate!==last?'<div class="fee-date">'+Number(r.dueDate.slice(5,7))+'월 '+Number(r.dueDate.slice(8))+'일 <span>'+DAYS[localDate(r.dueDate).getDay()]+'요일</span></div>':'';last=r.dueDate;const status=r.paid?'납부 완료':r.dueDate<today?'기한 지남':r.method==='auto'?'자동납부 예정':'납부 예정';return dateHeader+'<article class="fee-row"><span class="avatar" style="--child-color:'+childOf(r.childId).color+'">'+esc(childOf(r.childId).name[0])+'</span><div class="fee-name"><strong>'+esc(r.academy)+'</strong><small>'+esc(childOf(r.childId).name)+' · '+esc(METHODS[r.method])+(r.paid?' · '+r.payment.paidDate+' 납부':'')+'</small></div><div class="fee-amount"><strong>'+won(r.amount)+'</strong><span class="fee-status '+(r.paid?'paid':r.dueDate<today?'overdue':r.method==='auto'?'automatic':'')+'">'+status+'</span></div><div class="fee-actions"><button class="button small" data-action="payment" data-id="'+r.feeId+'">'+(r.paid?'납부 기록 수정':'납부 확인')+'</button><button class="text-button" data-action="fee" data-id="'+r.feeId+'">회비 설정</button></div></article>';}).join(''):'<div class="empty"><h3>등록된 학원비가 없어요</h3><p>매월 납부일, 금액, 자동납부·카드·송금 방식을 등록해 보세요.<br>등록된 다른 달 항목은 회비 설정 목록에서 편집할 수 있어요.</p></div>')+'</div><div class="fees-foot"><button class="text-button" data-action="fee-list">전체 회비 설정 목록</button><span>자동 결제·계좌 조회 기능이 아닙니다. 실제 납부는 직접 확인하세요.</span></div></section>';}
function editFee(id){if(!state.children.length){toast('자녀를 먼저 추가해 주세요.');editChild();return;}const f=state.fees.find(x=>x.id===id)||{childId:child==='all'?state.children[0].id:child,academy:'',amount:'',dueDay:5,method:'auto',startMonth:feeMonth,endMonth:'',note:''};editing={type:'fee',id};dialog(id?'학원비 반복 설정 수정':'학원비 납부일 등록',formWrap('fee','<div class="form-grid">'+select('childId','자녀',state.children.map(c=>[c.id,c.name]),f.childId)+input('academy','학원 · 회비 이름',f.academy,'text','required maxlength="80"')+input('amount','매월 예정 금액 (원)',f.amount,'number','required min="0" max="100000000" step="1"')+input('dueDay','매월 납부일 (1~31일)',f.dueDay,'number','required min="1" max="31" step="1"')+select('method','기본 납부 방식',Object.entries(METHODS),f.method)+input('startMonth','시작 월',f.startMonth,'month','required')+input('endMonth','종료 월 (선택)',f.endMonth,'month')+'</div><label>메모<textarea name="note" maxlength="500">'+esc(f.note)+'</textarea></label><p class="help">해당 일자가 없는 달은 말일로 표시합니다. 자동납부도 직접 완료 확인해야 합니다. 반복 설정을 바꿔도 이미 완료한 기록의 금액·방식·납부일은 유지합니다. 수강 종료 시 종료 월을 지정하세요.</p>',!!id));}
function editPayment(id){const r=feeRows(state,feeMonth).find(x=>x.feeId===id);if(!r){toast('이 달에 해당하는 회비가 없습니다.');return;}editing={type:'payment',feeId:id,month:feeMonth};dialog('납부 확인 · '+r.academy,formWrap('payment','<div class="notice neutral">'+esc(childOf(r.childId).name)+' · '+feeMonth+' 회비 · 예정일 '+r.dueDate+'<br>완료 기록은 실제 결제를 대신하지 않습니다.</div>'+select('status','납부 상태',[['pending','아직 납부 전 / 완료 취소'],['paid','실제 납부 완료']],'paid')+'<div class="form-grid">'+input('paidDate','실제 납부일',r.payment?.paidDate||iso(new Date()),'date','required')+input('amount','실제 납부 금액 (원)',r.amount,'number','required min="0" max="100000000" step="1"')+select('method','실제 납부 방식',Object.entries(METHODS),r.method)+'</div><label>납부 메모<textarea name="note" maxlength="500">'+esc(r.payment?.note||'')+'</textarea></label><p class="help">카드번호·계좌 비밀번호는 입력하지 마세요. 완료 취소는 해당 월의 기록만 지우고 반복 예정 항목은 유지합니다.</p>'));}
function feeList(){editing=null;dialog('전체 회비 설정 목록',state.fees.map(f=>'<div class="list-item"><span><strong>'+esc(f.academy)+'</strong><small>'+esc(childOf(f.childId).name)+' · 매월 '+f.dueDay+'일 · '+won(f.amount)+'<br>'+f.startMonth+' ~ '+(f.endMonth||'계속')+'</small></span><div class="buttons"><button class="button small" data-action="fee" data-id="'+f.id+'">편집</button></div></div>').join('')+'<button class="text-button" data-action="fee">+ 새 학원비 등록</button>');}


function defaultSchool(childId,day){const old=state.schedules.find(s=>s.childId===childId&&s.kind==='school'&&!s.date&&s.days.includes(day));return {id:uid(),childId,day,date:'',enabled:true,school:old?.place||'',regularStart:old?.start||'09:00',regularEnd:old?.end||'13:00',schoolTravel:old?.travel??10,schoolMode:old?.mode||'walk',after:[],care:{enabled:false,start:old?.end||'13:00',end:'16:00',teacher:'',room:'',phone:'',teacherPhone:'',note:''},pickup:{mode:'walk',vehicle:'',place:'',contactId:''},note:''};}
function schoolCall(number,label='교실 전화'){if(!realPhone(number))return '<span class="help">예시 번호 · 실제 연락처로 수정</span>';return '<a class="button small school-call" href="tel:'+esc(phone(number))+'">'+icon('phone')+esc(label)+'</a>';}
function schoolSummary(full){const kids=state.children.filter(c=>child==='all'||c.id===child);if(!kids.length)return '';return '<section class="school-summary" aria-label="학교 출발 및 돌봄 안내"><div class="info-heading"><h2>학교에서 나오는 시간 <span>'+selected+' · 계획 기준, 실제 퇴실 확인 아님</span></h2>'+(!full?'<button class="text-button" data-action="view" data-view="school">요일별 학교생활 설정 ›</button>':'')+'</div><div class="school-cards">'+kids.map(c=>{const p=schoolPlanFor(state,c.id,selected),day=localDate(selected).getDay(),btn='<button class="button small" data-action="school" data-child="'+c.id+'" data-day="'+day+'" data-date="'+selected+'">'+(p?'설정 수정':'학교생활 설정')+'</button>';if(!p)return '<article class="school-day-card"><div class="section-row"><strong>'+esc(c.name)+'</strong>'+btn+'</div><p class="help">요일마다 다른 정규수업·방과후·돌봄 시간을 설정하세요. 설정 전에는 기존 학교 일정이 유지됩니다.</p></article>';if(!p.enabled)return '<article class="school-day-card"><div class="section-row"><strong>'+esc(c.name)+' · 등교하지 않는 날</strong>'+btn+'</div><p class="help">'+(p.date?'이 날짜만 적용':'매주 '+DAYS[day]+'요일')+' · 학원 일정은 그대로 유지됩니다.</p></article>';const warnings=schoolWarnings(state,selected,c.id),segments=schoolSegments(p),care=p.care;return '<article class="school-day-card"><div class="section-row"><div><span class="eyebrow">'+esc(c.name)+' · '+esc(p.school)+(p.date?' · 날짜 예외':'')+'</span><div class="school-release"><b>'+schoolDeparture(p)+'</b><span>학교 출발 가능</span></div></div>'+btn+'</div><div class="school-chain"><span>정규 '+p.regularEnd+' 종료</span>'+p.after.map(a=>'<span>방과후 '+esc(a.title)+' '+a.end+'</span>').join('')+(care.enabled?'<span class="care-chip">돌봄 '+care.end+' 퇴실</span>':'')+'</div>'+(full?'<div class="school-segments">'+segments.map(s=>'<div><b>'+s.start+'–'+s.end+'</b><span>'+esc(s.title)+(s.kind==='care'?' · '+esc(care.room):'')+'</span></div>').join('')+'</div>':'')+(care.enabled?'<div class="care-contact"><div><b>'+esc(care.teacher)+' 선생님</b><small>'+esc(care.room)+' · '+esc(care.phone)+'</small></div>'+schoolCall(care.phone)+(care.teacherPhone?schoolCall(care.teacherPhone,'업무 전화'):'')+'</div>':'')+'<p class="school-pickup">학교 출발: '+esc(MODES[p.pickup.mode])+(p.pickup.vehicle?' · '+esc(p.pickup.vehicle):'')+(p.pickup.place?' · '+esc(p.pickup.place):'')+'</p>'+(warnings.length?'<div class="notice warn">'+warnings.map(esc).join('<br>')+'</div>':'')+'</article>';}).join('')+'</div></section>';}
function schoolHub(){const kids=state.children.filter(c=>child==='all'||c.id===child);return head('학교 · 방과후 · 돌봄','정규수업 종료부터 실제 학교 출발까지, 자녀별·요일별로 연결하세요.','<button class="button primary" data-action="school">'+icon('plus')+'학교생활 설정</button>')+'<div class="notice neutral">돌봄 이용 시 선생님 이름 · 교실명 · 교실 전화번호는 필수입니다. 업무 연락처는 추가로 기록할 수 있습니다. 기존 학교 일정은 삭제하지 않으며, 설정한 날짜·요일에만 새 학교생활 계획이 대신 표시됩니다.</div><section class="card school-week-card"><div class="section-row"><div class="period"><button class="icon-button" data-action="week" data-step="-1" aria-label="이전 학교 주">‹</button><b>'+week+' 주간</b><button class="icon-button" data-action="week" data-step="1" aria-label="다음 학교 주">›</button><button class="button small" data-action="today">오늘</button></div></div><div class="chips"><button class="chip '+(child==='all'?'active':'')+'" data-action="filter" data-id="all">모든 자녀</button>'+state.children.map(c=>'<button class="chip '+(child===c.id?'active':'')+'" data-action="filter" data-id="'+c.id+'">'+esc(c.name)+'</button>').join('')+'</div><div class="day-tabs">'+Array.from({length:7},(_,i)=>{const date=addDays(week,i);return '<button class="day-tab '+(date===selected?'selected':'')+'" data-action="day" data-date="'+date+'">'+DAYS[localDate(date).getDay()]+'<strong>'+localDate(date).getDate()+'</strong></button>';}).join('')+'</div><div class="school-week-list">'+kids.map(c=>'<div class="school-child-week"><h2>'+esc(c.name)+'의 요일별 학교 출발</h2><div class="school-week-grid">'+Array.from({length:5},(_,i)=>{const date=addDays(week,i),p=schoolPlanFor(state,c.id,date);return '<button class="school-week-day '+(date===selected?'chosen':'')+'" data-action="school" data-child="'+c.id+'" data-day="'+(i+1)+'" data-date="'+date+'"><b>'+DAYS[i+1]+'요일</b><strong>'+(p?(p.enabled?schoolDeparture(p):'휴업'):'미설정')+'</strong><small>'+(p?.enabled?'정규 '+p.regularEnd+'<br>방과후 '+p.after.length+'개 · '+(p.care.enabled?'돌봄 '+p.care.end:'돌봄 없음'):p?'등교하지 않음':'눌러서 설정')+'</small>'+(p?.date?'<span>이 날짜 예외</span>':'')+'</button>';}).join('')+'</div></div>').join('')+'</div></section>'+schoolSummary(true);}
function careContactsHTML(useToday=false){const contactDate=useToday?iso(new Date()):selected;const map=new Map();for(const c of state.children){const plans=[schoolPlanFor(state,c.id,contactDate),...state.schoolPlans.filter(p=>p.childId===c.id&&!p.date)];for(const p of plans){if(!p?.enabled||!p.care.enabled)continue;const k=p.childId+':'+p.care.teacher+':'+p.care.phone+':'+p.care.room;if(!map.has(k))map.set(k,{p,c});}}if(!map.size)return '';return '<section class="care-directory"><h3>돌봄 선생님 · 교실 연락망</h3><p class="help">'+(useToday?'오늘 ':'선택일 ')+contactDate+'의 연락처를 먼저 표시합니다. 함께 표시된 반복 설정 연락처는 해당 요일을 확인하세요.</p>'+[...map.values()].map(({p,c})=>'<div class="care-directory-row"><div><strong>'+esc(c.name)+' · '+esc(p.care.teacher)+' 선생님</strong><small>'+esc(p.school)+' / '+esc(p.care.room)+' / '+(p.date?p.date:DAYS[p.day]+'요일 설정')+'<br>'+esc(p.care.phone)+'</small></div><div class="inline-buttons">'+schoolCall(p.care.phone)+(p.care.teacherPhone?schoolCall(p.care.teacherPhone,'업무 전화'):'')+'</div></div>').join('')+'</section>';}
function afterRow(a){return '<fieldset class="after-row" data-af-row data-af-id="'+a.id+'"><div class="section-row"><legend>방과후 과목</legend><button type="button" class="text-button" data-action="af-remove">과목 삭제</button></div><div class="form-grid">'+input('af-title','과목 이름',a.title,'text','required maxlength="60"')+input('af-place','수업 교실',a.place,'text','maxlength="120"')+input('af-start','방과후 시작',a.start,'time','required')+input('af-end','방과후 종료',a.end,'time','required')+input('af-teacher','담당 선생님 (선택)',a.teacher,'text','maxlength="50"')+input('af-phone','담당 업무 전화 (선택)',a.phone,'tel','maxlength="30"')+'</div></fieldset>';}
